// Migration ledger for the frontend-rework epic, deleted at the cutover to the
// web UI together with the old UI. It maps every old-UI test behaviour to the
// new-UI test that guards it, and records the user's rulings on what is
// dropped, by design. Checked by web/src/parity/ledger.test.ts; the rules are
// in docs/frontend-testing.md → Parity ledger.

export const AREAS = ['header', 'sidebar', 'conversation', 'composer', 'dialogs', 'settings', 'views',
  'notifications', 'plugins-host', 'voice', 'android-shell', 'cross-cutting'] as const;
export type Area = (typeof AREAS)[number];
export type Viewport = 'desktop' | 'phone' | 'android';
/** `<repo-relative test file>::<full title>`; full title = describe titles + test title joined by ' > '. */
export type TestRef = `${string}::${string}`;

export type Ruling = { date: string /* YYYY-MM-DD */; ruling: string /* the user's words */ };
export const RULINGS = {
  'header-redesign': {
    date: '2026-10-10',
    ruling: "Drop all five: the rework's header redesign (refusal toast, new ⋮ order, md/768px Sync breakpoint, Auto-approve in ⋮ with a bar badge, two-line desktop header) is intentional.",
  },
  'old-ui-internals': {
    date: '2026-10-10',
    ruling: 'Drop P3: tests of old-UI internals with no counterpart in the new architecture.',
  },
  'settings-select-restore': {
    date: '2026-10-10',
    ruling: 'Drop P8: the Settings section picker is hash links now, so there is no form value for the browser to restore.',
  },
  'v3-chip-wording': {
    date: '2026-10-10',
    ruling: "V3 is intentional: the model-switch chip reads 'Switching to X' / 'Switch failed'.",
  },
  'phone-two-line-header': {
    date: '2026-10-10',
    ruling: 'User ruling. Port the rest of the row on Pixel 7 under /next/: controls on one row, nothing past the viewport, a long title gets an ellipsis without making the header taller, and no Sync in the bar. The 48px bound is dropped by user ruling.',
  },
  'v5-markdown-zoom': {
    date: '2026-10-10',
    ruling: 'V5 is intentional: images inside rendered markdown no longer open the zoom overlay.',
  },
  'v7-settings-models': {
    date: '2026-10-10',
    ruling: 'V7 is intentional: re-entering Settings opens Models.',
  },
  'p6-next-playwright-layout': {
    date: '2026-10-10',
    ruling: "/next/ Playwright layout checks replace the old UI's stylesheet assertions; such rows are ported against /next/ checks, not dropped.",
  },
  'wording-only': {
    date: '2026-10-11',
    ruling: "Drop the wording-only parts of doc/B27, doc/B12 and blocks/R11. The visual rework's goal is that every feature still works and is accessible; keeping the wording and dimensions exactly the same is not a goal. The features stay (interrupt-armed shows Interrupt now, a dead session cannot send, the usage line shows), only the exact text and glyphs are dropped.",
  },
  'old-stylesheet-mechanisms': {
    date: '2026-10-11',
    ruling: "Drop rows that pin an old stylesheet rule, class name or design token, while the feature stays reachable in /next: action groups collapse, hidden things stay hidden, touch devices reach hover-only controls, plugin frames are readable. Replaces the earlier 'P6 stays as a /next/ Playwright check' plan for these rows only.",
  },
  'layout-order-and-geometry': {
    date: '2026-10-11',
    ruling: 'Drop rows that pin old layout order or pixel geometry: body order and full width, equal control heights, an empty slot\'s height, and narrow re-stacking. The controls stay visible, reachable and free of overflow; those functional checks live in legacy-sidebar-lenses/R11, legacy-sidebar-strip/R7 and legacy-models-responsive/R1.',
  },
  'partial-rows-function-only': {
    date: '2026-10-11',
    ruling: 'Visual-rework goal: every feature still works and is accessible; keeping wording and dimensions exactly the same is not a goal. Partially in-scope rows are ported for their function only; their exact wording, glyphs, colours, pulse, exact px, hover fill and box containment are dropped.',
  },
  'test-scaffolding': {
    date: '2026-10-11',
    ruling: "Test scaffolding with no product behaviour: the old spec's self-checks and its full-height screenshot.",
  },
  'server-output-guarded-elsewhere': {
    date: '2026-10-11',
    ruling: "Server output, guarded outside the frontend ledger by tests/mcp-text-render.test.mjs › list_sessions renders every allowlisted field > awaitingWake renders as a label, both ways.",
  },
} as const satisfies Record<string, Ruling>;
export type RulingId = keyof typeof RULINGS;

export type Status<R extends string = RulingId> =
  | { kind: 'ported'; by: readonly [TestRef, ...TestRef[]] }
  | { kind: 'missing' }
  | { kind: 'regressed'; evidence: string }
  | { kind: 'dropped'; ruling: R };

export type OldSource =
  | { file: string; tests?: readonly string[] | 'rest'; formerly?: string }
  | { doc: 'docs/features.md'; section: string }; // a documented behaviour no old test guards

export interface Row<R extends string = RulingId> {
  id: string;
  old: OldSource;
  behaviour: string;
  viewports: readonly [Viewport, ...Viewport[]];
  area: Area;
  status: Status<R>;
}
/** Titles in an old-UI test file that test no old-UI behaviour: the cutover keeps them. */
export interface Survivor { file: string; tests: readonly string[]; note: string }

